import * as React from "react"
import { cn } from "@/lib/utils"
import "./glitchpage-effects.css"

interface GlitchTextProps extends React.HTMLAttributes<HTMLDivElement> {
  text?: string
  /** show a blinking cursor block after the text */
  cursor?: boolean
  /** glitch intensity */
  intensity?: "subtle" | "standard" | "loud"
}

const INTENSITY: Record<string, { base: string; a: string; b: string }> = {
  subtle: {
    base: "gp-glitch 6s ease-in-out infinite",
    a: "gp-glitch-offset 5s ease-in-out infinite",
    b: "gp-glitch-offset 7s ease-in-out infinite reverse",
  },
  standard: {
    base: "gp-glitch 3s ease-in-out infinite",
    a: "gp-glitch-offset 2.4s ease-in-out infinite",
    b: "gp-glitch-offset 3.2s ease-in-out infinite reverse",
  },
  loud: {
    base: "gp-glitch 1.6s steps(2) infinite",
    a: "gp-glitch-offset 1.2s steps(2) infinite",
    b: "gp-glitch-offset 1.6s steps(2) infinite reverse",
  },
}

export function GlitchText({
  className,
  text = "404",
  cursor = false,
  intensity = "standard",
  ...props
}: GlitchTextProps) {
  const anim = INTENSITY[intensity] ?? INTENSITY.standard
  return (
    <div
      className={cn(
        "relative inline-flex font-display font-black leading-none group",
        className
      )}
      style={{
        color: "var(--accent)",
        textShadow: "3px 0 var(--accent-2), -3px 0 var(--accent)",
        animation: anim.base,
      }}
      {...props}
    >
      <span className="relative z-10">{text}</span>
      <span
        className="absolute top-0 left-0 pointer-events-none"
        style={{
          color: "var(--accent-2)",
          clipPath: "inset(18% 0 56% 0)",
          animation: anim.a,
          mixBlendMode: "screen",
        }}
        aria-hidden="true"
      >
        {text}
      </span>
      <span
        className="absolute top-0 left-0 pointer-events-none"
        style={{
          color: "var(--accent)",
          clipPath: "inset(56% 0 12% 0)",
          animation: anim.b,
          mixBlendMode: "screen",
        }}
        aria-hidden="true"
      >
        {text}
      </span>
      {cursor && (
        <span
          className="ml-1 inline-block"
          style={{
            width: "0.5em",
            height: "0.82em",
            alignSelf: "flex-end",
            marginBottom: "0.1em",
            background: "var(--accent)",
            animation: "gp-blink 1.1s steps(1) infinite",
          }}
          aria-hidden="true"
        />
      )}
    </div>
  )
}

/* Glitchpage theme effects — GLITCHPAGE remix
   RGB-split glitch · drift grid · scanlines · blink cursor.
   Upgraded to match the lab Glance "GLITCHPAGE // LAB NOC" remix. */

@keyframes gp-glitch {
  0%, 88%, 100% { transform: translate(0); }
  90% { transform: translate(-3px, 2px); }
  92% { transform: translate(3px, -1px); }
  94% { transform: translate(-2px, -2px); }
  96% { transform: translate(2px, 1px); }
  98% { transform: translate(-1px, 0); }
}

@keyframes gp-glitch-offset {
  0%, 78%, 100% { transform: translate(0); }
  82% { transform: translate(-8px, 5px); }
  86% { transform: translate(5px, -3px); }
  90% { transform: translate(-4px, 3px); }
  94% { transform: translate(3px, -2px); }
}

@keyframes gp-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

@keyframes gp-drift {
  to { background-position: 0 0, 0 0, 0 28px, 28px 0; }
}

@keyframes gp-flicker {
  0%, 92%, 100% { opacity: 1; }
  93% { opacity: 0.45; }
  94% { opacity: 1; }
  96% { opacity: 0.7; }
  97% { opacity: 1; }
}

/* ---- utility: drift grid background ---- */
.gp-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background-image:
    linear-gradient(var(--glitch-grid, rgba(55, 230, 255, 0.06)) 1px, transparent 1px),
    linear-gradient(90deg, var(--glitch-grid-2, rgba(255, 61, 143, 0.05)) 1px, transparent 1px);
  background-size: 28px 28px;
  animation: gp-drift 26s linear infinite;
}

/* ---- utility: scanline overlay ---- */
.gp-scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background: repeating-linear-gradient(
    0deg,
    var(--glitch-scan, rgba(0, 0, 0, 0.18)) 0,
    var(--glitch-scan, rgba(0, 0, 0, 0.18)) 1px,
    transparent 1px,
    transparent 3px
  );
  mix-blend-mode: multiply;
  opacity: 0.55;
}

/* ---- utility: blink cursor block ---- */
.gp-cursor {
  display: inline-block;
  width: 0.5em;
  height: 0.9em;
  transform: translateY(0.12em);
  background: var(--accent, #ff3d8f);
  animation: gp-blink 1.1s steps(1) infinite;
}

/* ---- utility: subtle label glitch on hover ---- */
.gp-label-glitch {
  transition: text-shadow 0.2s, color 0.2s;
}
.gp-label-glitch:hover {
  color: var(--fg, #e8eafc);
  text-shadow: 1.5px 0 var(--accent-2, #37e6ff), -1.5px 0 var(--accent, #ff3d8f);
  animation: gp-glitch 0.5s steps(2) infinite;
}

@media (prefers-reduced-motion: reduce) {
  .gp-grid,
  .gp-cursor,
  .gp-label-glitch:hover { animation: none !important; }
}

